<?php $title='Your cart'; require 'includes/header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['product_id']??0);if(isset($_POST['add'])||isset($_POST['buy'])){$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+max(1,(int)($_POST['quantity']??1));$_SESSION['flash']='Item added to your cart.';if(isset($_POST['buy'])){header('Location: '.url('checkout.php'));exit;}} if(isset($_POST['update']))foreach($_POST['qty']??[] as $k=>$v){if((int)$v>0)$_SESSION['cart'][(int)$k]=(int)$v;else unset($_SESSION['cart'][(int)$k]);} if(isset($_POST['remove']))unset($_SESSION['cart'][$id]);header('Location: '.url('cart.php'));exit;}$items=[];$subtotal=0;if($pdo&&!empty($_SESSION['cart'])){foreach($_SESSION['cart'] as $id=>$qty){$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);if($p=$q->fetch()){$p['qty']=$qty;$p['line']=($p['discount_price']?:$p['price'])*$qty;$subtotal+=$p['line'];$items[]=$p;}}}$gst=$subtotal*.18;$shipping=$subtotal>=999||$subtotal==0?0:99; ?>
<h1 class="section-title mb-4">Your shopping cart</h1><?php if(!$items): ?><div class="text-center py-5"><i class="fa-solid fa-bag-shopping fs-1 text-muted"></i><h4 class="mt-3">Your cart is empty</h4><a class="btn btn-primary rounded-pill" href="<?=url('products.php')?>">Continue shopping</a></div><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-4"><div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Product</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><img class="rounded me-2" src="<?=url(e($p['image']))?>"> <?=e($p['name'])?></td><td><?=money($p['discount_price']?:$p['price'])?></td><td><input class="form-control" style="width:75px" type="number" min="0" name="qty[<?=$p['id']?>]" value="<?=$p['qty']?>"></td><td><?=money($p['line'])?></td><td><button class="btn btn-sm text-danger" name="remove" value="1" formaction="<?=url('cart.php')?>" onclick="this.form.product_id.value=<?=$p['id']?>"><i class="fa fa-trash"></i></button></td></tr><?php endforeach; ?></tbody></table></div></div><button name="update" class="btn btn-outline-primary btn-sm mt-3">Update cart</button><input type="hidden" name="product_id" value="0"></div><div class="col-lg-4"><div class="card border-0 shadow-sm p-4"><h5>Order summary</h5><p class="d-flex justify-content-between"><span>Subtotal</span><strong><?=money($subtotal)?></strong></p><p class="d-flex justify-content-between"><span>GST (18%)</span><strong><?=money($gst)?></strong></p><p class="d-flex justify-content-between"><span>Shipping</span><strong><?=money($shipping)?></strong></p><hr><h5 class="d-flex justify-content-between"><span>Grand total</span><span class="price"><?=money($subtotal+$gst+$shipping)?></span></h5><a href="<?=url('checkout.php')?>" class="btn btn-primary w-100 rounded-pill mt-3">Checkout</a></div></div></div></form><?php endif; require 'includes/footer.php'; ?>
